package com.zy.zhangyun;

import android.content.Context;import android.graphics.*;import android.util.AttributeSet;import android.view.View;import java.util.*;

public class TrendChartView extends View {
  private final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);private Map<String,List<Double>> data=new LinkedHashMap<>();private String first="",last="";private final int[] colors={Color.rgb(215,25,32),Color.rgb(96,165,250),Color.rgb(250,204,21),Color.rgb(244,114,182),Color.rgb(167,139,250),Color.rgb(45,212,191)};
  public TrendChartView(Context c,AttributeSet a){super(c,a);p.setTypeface(Typeface.create("sans",Typeface.NORMAL));}
  public void setSeries(Map<String,List<Double>> value,String start,String end){data=value==null?new LinkedHashMap<>():value;first=start;last=end;invalidate();}
  protected void onDraw(Canvas c){super.onDraw(c);float w=getWidth(),h=getHeight(),l=12,r=12,t=32,b=30;p.setColor(Color.rgb(16,32,56));c.drawRoundRect(0,0,w,h,18,18,p);if(data.isEmpty()){p.setColor(Color.rgb(145,164,189));p.setTextSize(14);p.setTextAlign(Paint.Align.CENTER);c.drawText("暂无走势图数据",w/2,h/2,p);return;}float pw=w-l-r,ph=h-t-b;double low=Double.MAX_VALUE,high=-Double.MAX_VALUE;
    for(List<Double> values:data.values())if(!values.isEmpty()){double base=values.get(0);for(double value:values){double ratio=value/base;low=Math.min(low,ratio);high=Math.max(high,ratio);}}double span=high-low;if(span<.002){double mid=(high+low)/2;low=mid-.001;high=mid+.001;}else{low-=span*.14;high+=span*.14;}span=high-low;
    int n=0;for(Map.Entry<String,List<Double>> entry:data.entrySet()){List<Double> values=entry.getValue();if(values.size()<2)continue;double base=values.get(0),rawHigh=-Double.MAX_VALUE,rawLow=Double.MAX_VALUE;int highAt=0,lowAt=0;Path path=new Path();for(int i=0;i<values.size();i++){double value=values.get(i);if(value>rawHigh){rawHigh=value;highAt=i;}if(value<rawLow){rawLow=value;lowAt=i;}float x=l+pw*i/(values.size()-1);float y=t+ph*(float)((high-value/base)/span);if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}int color=colors[n%colors.length];p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2.6f);p.setColor(color);c.drawPath(path,p);
      float hx=l+pw*highAt/(values.size()-1),hy=t+ph*(float)((high-rawHigh/base)/span),lx=l+pw*lowAt/(values.size()-1),ly=t+ph*(float)((high-rawLow/base)/span);p.setStyle(Paint.Style.FILL);p.setColor(color);c.drawCircle(hx,hy,4,p);c.drawCircle(lx,ly,4,p);p.setTextSize(10);p.setTextAlign(hx>w-78?Paint.Align.RIGHT:Paint.Align.LEFT);c.drawText("高 "+String.format(Locale.US,"%.5f",rawHigh),hx+(hx>w-78?-5:5),hy-7,p);p.setTextAlign(lx>w-78?Paint.Align.RIGHT:Paint.Align.LEFT);c.drawText("低 "+String.format(Locale.US,"%.5f",rawLow),lx+(lx>w-78?-5:5),ly+15,p);
      p.setTextSize(12);p.setTextAlign(Paint.Align.LEFT);c.drawCircle(l+n*62,t-17,4,p);p.setColor(Color.rgb(230,238,249));c.drawText(entry.getKey(),l+8+n*62,t-13,p);n++;}p.setColor(Color.rgb(145,164,189));p.setTextSize(10);p.setTextAlign(Paint.Align.LEFT);c.drawText(first,l,h-10,p);p.setTextAlign(Paint.Align.RIGHT);c.drawText(last,w-r,h-10,p);}
}
